# ReserveEntry: dataclass + validator
from dataclasses import dataclass, field
from typing import Any

@dataclass
class Reserveentry:
    entry_id: str = None  # ID
    claim_id: str = None  # FK
    reserve_usd: float = None  # USD
    posted_at: str = None  # ISO 8601
    actuary: str = None  # Actuary

REQUIRED = ["entry_id", "claim_id", "reserve_usd", "posted_at"]

def validate(rec: dict) -> list:
    errors = []
    for f in REQUIRED:
        if f not in rec or rec[f] is None:
            errors.append(f'missing: {f}')
    return errors

sample = {'entry_id': 'RSV-2201', 'claim_id': 'CL-2026-44120', 'reserve_usd': 4200, 'posted_at': '2026-05-21', 'actuary': 'act-02'}
print('validation errors:', validate(sample))
print('record ok:', not validate(sample))

